总数 = 0
for _ in range(n):
    一份 = int(input())
    try:
        if 一份 < 0:
            raise 鱼干不够(f"{一份} 这条不对劲喵")
        总数 += 一份
    except 鱼干不够 as e:
        print("逮住了：", e)
print("一共", n, "份，总数", 总数)

